'use strict';
// Presentation and navigation for the media library / research workspace.
// Original media, timeline clocks and processing remain owned by existing modules.
const Studio=(()=>{
 let libraryScroll=0, editor=null, savingNote=false;
 const routeNames={library:'首页',analysis:'拉片',replica:'复刻','ai-making':'AI制作',frames:'画面',music:'声音',settings:'设置'};
 const glyphs={shots:'film',clips:'film',recent:'clock',images:'image',audio:'audio',music:'music',frames:'image',sound:'audio',subtitles:'captions',transcript:'captions',notes:'note'};
 const activeClips=p=>(p.research_clips||[]).filter(c=>!c.deleted);
 const frameAt=(p,t)=>p.shots?.find(s=>t>=s.start&&t<s.end)?.thumbnail_url||p.shots?.[0]?.thumbnail_url||'';
 const title=p=>titleOf(p).replace(/\.[^.]+$/,'');
 const pictures=(p,start=0,end=p.duration,count=3)=>Array.from({length:count},(_,i)=>frameAt(p,start+(end-start)*(i+.15)/count));
 const img=(src,alt='',cls='')=>{const source=safeLocalUrl(src);return source?`<img src="${esc(source)}" alt="${esc(alt)}" class="${esc(cls)}" loading="lazy">`:`<span class="media-missing">${icon('film')}</span>`;};
 function videoCard(p){const clips=activeClips(p),shots=p.analysis||p.shots.length>1?p.shots.length:0,id=esc(p.id);return `<article class="media-card ${S.p?.id===p.id?'current':''}"><button class="media-cover" data-project="${id}" aria-label="研究 ${esc(title(p))}">${img(frameAt(p,Math.min(p.duration*.12,30)))}<span class="cover-play">${icon('play')}</span><span class="cover-duration">${clock(p.duration)}</span></button><div class="media-strip" aria-hidden="true">${pictures(p).map(s=>img(s)).join('')}</div><div class="media-card-body"><div class="row"><button class="media-title" data-project="${id}">${esc(title(p))}</button><button class="icon-btn" data-project-menu="${id}" aria-label="${esc(p.name)} 更多操作">${icon('more')}</button></div><div class="media-meta"><span>${p.width} × ${p.height}</span><span>${p.source?.platform?esc(p.source.platform):'本地视频'}</span></div><div class="media-card-foot"><span>${icon('film')}${shots?shots+' 个镜头':p.status==='processing'?'镜头识别中':'待识别镜头'}</span><span>${icon('folder')}${clips.length} 个研究分镜</span><button class="icon-btn enter-study" data-project="${id}" aria-label="进入拉片">${icon('arrow')}</button></div></div></article>`;}
 const cardDate=value=>{const date=new Date(value);return Number.isNaN(date.getTime())?'':date.toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit'});};
 function clipCard(c,p,global=false){const frames=c.frames.filter(f=>!f.deleted),menu=`clip-menu-${domId(p.id)}-${domId(c.id)}`,clipId=esc(c.id),owner=esc(p.id);return `<article class="research-card visual-media-card"><button class="research-cover" ${global?`data-studio-clip="${clipId}" data-owner="${owner}"`:`data-clip-action="choose" data-id="${clipId}"`} aria-label="打开分镜 ${esc(c.title)}">${img(frames[0]?.url||frameAt(p,c.start))}<span class="card-caption"><span class="card-copy"><strong>${esc(c.title)}</strong><small>${esc(cardDate(c.created_at))} · ${clock(c.start)}</small></span><span class="card-badges">${frames.length?`<span>${frames.length} 画面</span>`:''}<span>${clock(c.end-c.start)}</span></span></span></button><button class="icon-btn card-more" popovertarget="${menu}" aria-label="${esc(c.title)} 更多操作">${icon('more')}</button><div id="${menu}" popover class="media-card-menu" role="menu">${[['open','打开分镜','film'],['edit','改名或调整范围','edit'],['delete','移除分镜','trash']].map(([action,label,glyph])=>`<button role="menuitem" ${action==='open'?'autofocus':''} data-card-action="${action}" data-id="${clipId}" data-owner="${owner}">${icon(glyph)}${label}</button>`).join('')}</div></article>`;}
 function frameCard(f,c){const menu=`frame-menu-${domId(c.id)}-${domId(f.id)}`,frameId=esc(f.id),clipId=esc(c.id),source=safeLocalUrl(f.url),number=esc(String(f.number).padStart(2,'0'));return `<article class="visual-media-card"><button class="scene-image" data-clip-action="seek" data-time="${esc(f.time)}" aria-label="定位画面 ${esc(f.number)} · ${clock(f.time)}">${img(source,'画面 '+f.number)}<span class="card-caption"><span class="card-copy"><strong>画面 ${number}</strong><small>${esc(cardDate(f.created_at))}${f.outside?' · 范围外':''}</small></span><span class="card-badges"><span>${clock(f.time)}</span></span></span></button><button class="icon-btn card-more" popovertarget="${menu}" aria-label="画面 ${esc(f.number)} 更多操作">${icon('more')}</button><div id="${menu}" popover class="media-card-menu" role="menu"><a role="menuitem" href="${esc(source)}" download="${esc(safeDownloadName(f.filename))}">${icon('download')}保存图片副本</a><button role="menuitem" data-clip-action="reveal" data-file="${frameId}" data-clip="${clipId}">${icon('folder')}在访达中显示</button><button role="menuitem" data-clip-action="remove-frame" data-item="${frameId}">${icon('trash')}移除画面</button></div></article>`;}
 function musicCard(a){const source=S.projects.find(p=>p.id===a.projectId),cover=safeLink(a.artwork_url),id=esc(a.id),owner=esc(a.projectId||''),target=a.projectId?`data-music-source="${id}" data-owner="${owner}"`:`data-local-play="${id}"`;return `<article class="music-card"><button class="music-art" ${target} aria-label="${a.projectId?'回到配乐位置':'试听'} ${esc(a.title)}">${cover?`<img src="${esc(cover)}" alt="${esc(a.title)} 封面" loading="lazy" referrerpolicy="no-referrer">`:icon('music')}<span class="cover-play">${icon(a.projectId?'arrow':'play')}</span></button><div class="music-card-copy"><strong>${esc(a.title)}</strong><p>${esc(a.artist||'未知作者')}</p><div class="chips">${chipList(tagsOf(a))}</div><button class="music-card-source" ${target}>${icon(a.projectId?'film':'folder')}<span>${source?esc(title(source))+' · '+clock(a.time):'本地声音'}</span></button><div class="music-card-actions"><button class="button" ${target}>${icon(a.projectId?'arrow':'play')}${a.projectId?'回到配乐位置':'试听声音'}</button><span class="spacer"></span>${iconAction('编辑音乐标签','music-tags','tag',`data-id="${id}" data-owner="${owner}"`)}${iconAction('移除记录','music-remove','trash',`data-id="${id}" data-owner="${owner}"`)}</div></div></article>`;}
 function libraryPage(){return `<section class="catalog" id="catalog"><div class="catalog-heading"><div><h2>你的素材，值得细看。</h2><p>从一段参考，开始一次研究。</p></div><button class="button primary" data-action="import">${icon('plus')}导入视频</button></div><div class="catalog-tools"><label class="search">${icon('search')}<input id="library-search" placeholder="搜索视频、标签或来源" aria-label="搜索视频" value="${esc(S.libraryText)}"></label><button class="button ${S.filters?'active':''}" data-action="filters">${icon('filter')}筛选</button><span class="spacer"></span><span id="library-count" class="muted"></span><select id="library-sort" aria-label="视频排序">${[['created_at','最近导入'],['name','名称'],['duration','片长']].map(([v,n])=>`<option value="${v}" ${v===S.sort?'selected':''}>${n}</option>`).join('')}</select>${iconAction('切换升降序','sort-direction','arrow')}</div><div id="library-filters"></div><div class="catalog-section-title"><h3>视频素材</h3><span>点击封面进入拉片</span></div><div id="library-grid" class="catalog-grid"></div><section id="catalog-clips"></section><div class="catalog-drop">${icon('upload')}<span>也可以将视频拖到这里导入</span></div></section>`;}
 function paintCatalog(){const root=$('#catalog-clips');if(!root)return;const projects=sortedProjects();const clips=projects.flatMap(p=>activeClips(p).map(c=>({c,p})));root.innerHTML=clips.length?`<div class="catalog-section-title"><h3>研究分镜 <span>${clips.length}</span></h3><span>画面 · 声音 · 观察</span></div><div class="research-grid">${clips.map(({c,p})=>clipCard(c,p,true)).join('')}</div>`:'';}
 function mount(){const catalog=$('#catalog');if(catalog){paintCatalog();catalog.scrollTop=libraryScroll;catalog.addEventListener('scroll',()=>libraryScroll=catalog.scrollTop,{passive:true});}syncPanels();}
 function setupPlayer(){
  const menu=$('#player-more-menu'),trigger=$('#player-more');if(!menu||!trigger)return;
  menu.addEventListener('beforetoggle',event=>{trigger.setAttribute('aria-expanded',String(event.newState==='open'));if(event.newState==='open'){const rect=trigger.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(rect.right-212,window.innerWidth-220))+'px';menu.style.top=(rect.bottom+6)+'px';}});
  menu.addEventListener('toggle',()=>{if(menu.matches(':popover-open'))menu.querySelector('button')?.focus();});
  menu.addEventListener('click',event=>{if(event.target.closest('[data-action]')){menu.hidePopover();trigger.focus();}});
  menu.addEventListener('keydown',event=>{const buttons=[...menu.querySelectorAll('button')],index=buttons.indexOf(document.activeElement);let next;if(event.key==='ArrowDown')next=(index+1)%buttons.length;if(event.key==='ArrowUp')next=(index+buttons.length-1)%buttons.length;if(event.key==='Home')next=0;if(event.key==='End')next=buttons.length-1;if(next!==undefined){event.preventDefault();event.stopPropagation();buttons[next].focus();}});
  $('#preview-scale').addEventListener('change',event=>{const stage=$('.player-stage'),scale=Number(event.target.value);stage.style.setProperty('--preview-scale',scale);});
 }
 document.addEventListener('keydown',event=>{const menu=$('#player-more-menu:popover-open')||$('#player-quality-menu:popover-open')||$('.media-card-menu:popover-open');if(event.key==='Escape'&&menu){event.preventDefault();event.stopImmediatePropagation();menu.hidePopover();(menu.classList.contains('media-card-menu')?document.querySelector(`[popovertarget="${menu.id}"]`):$(menu.id==='player-quality-menu'?'#player-quality':'#player-more'))?.focus();}},true);
 function syncPanels(){const area=$('.work-area');if(!area)return;area.classList.toggle('inspector-hidden',!S.collectionOpen);$('[data-collection-toggle]')?.setAttribute('aria-pressed',String(S.collectionOpen));}
 function revealPanel(){S.collection='shots';S.collectionOpen=true;$('.collection')?.classList.add('open');syncPanels();}
 function clockPaint(){const c=Clips.active(),label=$('#clock-context'),secondary=$('#source-clock'),total=$('#clock-duration');if(label)label.textContent='原片';if($('#time'))$('#time').textContent=clock(S.position);if(total)total.textContent=clock(S.p.duration);if(secondary)secondary.textContent=c&&ClipLogic.inside(c,S.position)?'分镜内 '+clock(S.position-c.start):Number(S.p.fps).toFixed(2)+' fps';}
 function toolbar(){return '';}
 function fileCards(files,c){return files.map(f=>{const source=safeLocalUrl(f.url);return `<div class="file-card"><span class="file-type">${icon(/\.png$/i.test(f.filename)?'image':'audio')}</span><div><strong>${esc(f.kind==='vocals'?'人声':f.kind==='background'?'背景声':f.kind==='original'?'原音':/人声/.test(f.filename)?'人声':/背景声/.test(f.filename)?'背景声':/原音/.test(f.filename)?'原音':'关键画面')}</strong><details class="clip-file"><summary>文件详情</summary><p>${esc(f.filename)}<br>${esc(f.folder)}</p></details></div><span class="spacer"></span><a class="icon-btn" href="${esc(source)}" download="${esc(safeDownloadName(f.filename))}" title="保存副本" aria-label="保存 ${esc(f.filename)}">${icon('download')}</a><button class="icon-btn" data-clip-action="reveal" data-file="${esc(f.id)}" data-clip="${esc(c.id)}" title="在访达中显示" aria-label="在访达中显示">${icon('folder')}</button></div>`;}).join('');}
 const draftKey=m=>`research-note:${m.projectId}:${m.id}:${m.note_id||'new'}`;
 function noteEditor(c){if(!editor||editor.id!==c.id||editor.projectId!==S.p.id)return '';return `<div class="inline-note"><div class="row">${icon('note')}<strong>${editor.note_id?'编辑观察':'记录观察'}</strong><span class="spacer"></span><time>${clock(editor.time)}</time></div><textarea id="studio-note" aria-label="分镜笔记" placeholder="这一帧的构图、文字动效，或声音衔接…" maxlength="10000">${esc(editor.text)}</textarea><div class="row"><small>草稿保存在本机</small><span class="spacer"></span><button class="icon-btn" data-studio-action="note-close" aria-label="收起笔记" title="收起">${icon('close')}</button><button class="button primary" data-studio-action="note-save">${icon('check')}保存</button></div><p id="studio-note-error" role="alert"></p></div>`;}
 function openNote(id){const c=Clips.active();if(!c)return;S.autoplay=false;$('#video')?.pause();const n=c.notes.find(n=>n.id===id),m={projectId:S.p.id,id:c.id,expected_revision:c.revision,note_id:n?.id,time:n?.time??S.position};if(!ClipLogic.inside(c,m.time))throw new Error('请先定位到分镜内。');editor={...m,text:readSetting(draftKey(m),n?.text||'')};revealPanel();Clips.showTab('notes');$('#studio-note')?.focus();}
 async function saveInlineNote(button){if(!editor||savingNote)return;const targetEditor=editor,m={...editor};const field=$('#studio-note');m.text=field.value;if(!m.text.trim()){field.focus();$('#studio-note-error').textContent='写下一条观察后再保存。';return;}savingNote=true;button.disabled=true;field.readOnly=true;try{const result=await api(url(m.projectId,'/research'),{action:'note',...m});upsert(result.project);if(editor===targetEditor){writeSetting(draftKey(m),null);editor=null;}refreshViews();toast('观察已保存，可点击时间回看。');}catch(error){const errorNode=$('#studio-note-error');if(errorNode)errorNode.textContent=error.message;else toast(error.message);}finally{savingNote=false;button.disabled=false;field.readOnly=false;}}
 function empty(kind,text,detail=''){return `<div class="visual-empty">${icon(kind)}<strong>${esc(text)}</strong>${detail?`<p>${esc(detail)}</p>`:''}</div>`;}
 document.addEventListener('click',async e=>{const el=e.target.closest('[data-studio-action],[data-studio-clip]');if(!el||el.disabled)return;try{if(el.dataset.studioClip){await selectProject(el.dataset.owner,{autoplay:false});Clips.choose(el.dataset.studioClip);return;}if(el.dataset.studioAction==='note-save')await saveInlineNote(el);if(el.dataset.studioAction==='note-close'){editor=null;renderCollection();}}catch(err){toast(err.message)}});
 document.addEventListener('click',async e=>{const el=e.target.closest('[data-card-action]');if(!el)return;el.closest('[popover]')?.hidePopover();try{if(S.p?.id!==el.dataset.owner||S.view!=='analysis')await selectProject(el.dataset.owner,{autoplay:false});await Clips.cardAction(el.dataset.id,el.dataset.cardAction);}catch(error){toast(error.message)}});
 document.addEventListener('beforetoggle',e=>{const menu=e.target;if(!menu.classList?.contains('media-card-menu')||e.newState!=='open')return;const trigger=document.querySelector(`[popovertarget="${menu.id}"]`),rect=trigger.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(rect.right-200,innerWidth-208))+'px';menu.style.top=Math.max(8,Math.min(rect.bottom+6,innerHeight-148))+'px';},true);
 document.addEventListener('click',e=>{const item=e.target.closest('.media-card-menu [role="menuitem"]');item?.closest('[popover]')?.hidePopover();},true);
 document.addEventListener('keydown',e=>{const menu=e.target.closest('.media-card-menu');if(!menu)return;const items=[...menu.querySelectorAll('[role="menuitem"]')],index=items.indexOf(document.activeElement);let next;if(e.key==='ArrowDown')next=(index+1)%items.length;if(e.key==='ArrowUp')next=(index+items.length-1)%items.length;if(next!==undefined){e.preventDefault();e.stopPropagation();items[next].focus();}},true);
 document.addEventListener('input',e=>{if(e.target.id==='studio-note'&&editor){editor.text=e.target.value;writeSetting(draftKey(editor),editor.text);}});
 document.addEventListener('keydown',e=>{if(e.target.id==='studio-note'&&(e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();const b=$('[data-studio-action="note-save"]');if(b&&!b.disabled)saveInlineNote(b);}});
 return {frameCard,cardDate,setupPlayer,routeNames,glyphs,frameAt,img,videoCard,clipCard,musicCard,libraryPage,paintCatalog,mount,syncPanels,revealPanel,clockPaint,toolbar,fileCards,noteEditor,openNote,empty};
})();
